    { id: 18245, theme: "Gastronomie", d: 3.5, q: "Quel mode de cuisson doux place un récipient dans un autre rempli d’eau chaude ?", a: ["Le bain-marie", "Bain-marie", "Bain marie"], exp: "Il porterait le nom de Marie, une alchimiste de l’Antiquité." },
    { id: 18246, theme: "Gastronomie", d: 3.5, q: "Quelle sauce au beurre et aux jaunes d’œufs nappe les œufs Bénédicte ?", a: ["La sauce hollandaise", "Hollandaise", "Sauce hollandaise"], exp: "La béarnaise en est une cousine, à l’échalote et à l’estragon." },
    { id: 18247, theme: "Gastronomie", d: 3.5, q: "Quelle sauce au beurre et à l’échalote est une spécialité nantaise pour le poisson ?", a: ["Le beurre blanc", "Beurre blanc", "Beurre nantais"], exp: "Née sur les bords de Loire à la fin du XIXe siècle." },
    { id: 18248, theme: "Gastronomie", d: 3.5, q: "Quel petit fagot de thym, laurier et persil parfume les bouillons ?", a: ["Le bouquet garni", "Bouquet garni"], exp: "On le retire avant de servir." },
    { id: 18249, theme: "Gastronomie", d: 3.6, q: "Quelle herbe à fines tiges creuses a un goût d’oignon doux ?", a: ["La ciboulette", "Ciboulette"], exp: "On la coupe aux ciseaux." },
    { id: 18250, theme: "Gastronomie", d: 3.6, q: "Quelle herbe aromatique est indispensable sur une pizza, avec la tomate ?", a: ["L’origan", "Origan"], exp: "Proche de la marjolaine." },
    { id: 18251, theme: "Gastronomie", d: 3.6, q: "Quelle herbe aux feuilles en aiguilles parfume l’agneau et les pommes de terre au four ?", a: ["Le romarin", "Romarin"], exp: "Son nom latin veut dire « rosée de la mer »." },
    { id: 18252, theme: "Gastronomie", d: 3.6, q: "Quelle épice râpée parfume la béchamel et la purée ?", a: ["La noix de muscade", "Muscade", "Noix de muscade"], exp: "Elle vient des îles Banda, en Indonésie." },
    { id: 18253, theme: "Gastronomie", d: 3.7, q: "Quelle herbe fraîche, aussi appelée persil arabe, divise : certains lui trouvent un goût de savon ?", a: ["La coriandre", "Coriandre"], exp: "Ce dégoût serait en partie génétique." },
    { id: 18254, theme: "Gastronomie", d: 3.7, q: "Quelle soupe traditionnelle du Maghreb est servie pour rompre le jeûne du ramadan ?", a: ["La chorba", "Chorba"], exp: "Au Maroc, on sert plutôt la harira." },
    { id: 18255, theme: "Gastronomie", d: 3.7, q: "Quels raviolis japonais grillés d’un côté viennent du jiaozi chinois ?", a: ["Les gyozas", "Gyoza", "Gyozas"], exp: "Servis avec une sauce soja vinaigrée." },
    { id: 18256, theme: "Gastronomie", d: 3.7, q: "Comment appelle-t-on les petites bouchées cantonaises cuites à la vapeur dans des paniers en bambou ?", a: ["Les dim sum", "Dim sum", "Dim sums"], exp: "Traditionnellement servies avec le thé." },
    { id: 18257, theme: "Gastronomie", d: 3.8, q: "Quelles épaisses nouilles japonaises de blé se mangent en bouillon ?", a: ["Les udon", "Udon", "Udons"], exp: "Plus épaisses que les ramen et les soba." },
    { id: 18258, theme: "Gastronomie", d: 3.8, q: "Comment appelle-t-on le poisson cru tranché, servi sans riz, au Japon ?", a: ["Le sashimi", "Sashimi", "Sashimis"], exp: "Le sushi, lui, contient toujours du riz vinaigré." },
    { id: 18259, theme: "Gastronomie", d: 3.8, q: "Quels petits rouleaux japonais entourés d’algue nori contiennent riz et poisson ?", a: ["Les makis", "Maki", "Makis"], exp: "Le californien (california roll) a le riz à l’extérieur." },
    { id: 18262, theme: "Gastronomie", d: 3.9, q: "Quel sucre roux de canne, en cristaux, sucre souvent les crêpes ?", a: ["La cassonade", "Cassonade"], exp: "Différente de la vergeoise, faite de betterave." },
    { id: 18263, theme: "Gastronomie", d: 4.0, q: "Comment appelle-t-on les fins cristaux de sel récoltés à la surface des marais salants ?", a: ["La fleur de sel", "Fleur de sel"], exp: "Celle de Guérande est la plus célèbre." },
    { id: 18264, theme: "Gastronomie", d: 2.5, q: "Quelle tarte au citron est recouverte d’un nuage blanc doré au chalumeau ?", a: ["La tarte au citron meringuée", "Tarte au citron meringuée"], exp: "Une meringue italienne, faite avec un sirop chaud." },
    { id: 18265, theme: "Gastronomie", d: 2.0, q: "Quel nœud de pain salé, en forme de cœur, est le symbole des boulangers alsaciens ?", a: ["Le bretzel", "Bretzel", "Bretzels"], exp: "Trempé dans une solution de bicarbonate avant cuisson." },
    { id: 18266, theme: "Gastronomie", d: 2.6, q: "Quel gâteau roulé viennois en pâte très fine est garni de pommes et de cannelle ?", a: ["Le strudel", "Strudel", "Apfelstrudel"], exp: "La pâte doit être si fine qu’on peut lire un journal au travers." },
    { id: 18267, theme: "Gastronomie", d: 1.7, q: "Quel nom italien donne-t-on à la crème glacée artisanale ?", a: ["Le gelato", "Gelato"], exp: "Plus dense et moins grasse que la glace américaine." },
    { id: 18268, theme: "Gastronomie", d: 2.4, q: "Quelles petites boulettes italiennes de pommes de terre et de farine se servent avec du beurre et de la sauge ?", a: ["Les gnocchis", "Gnocchi", "Gnocchis"], exp: "On les égoutte dès qu’ils remontent à la surface." },
    { id: 18269, theme: "Gastronomie", d: 1.0, q: "Quel petit fromage frais en forme de cylindre, emballé dans du papier, se mange souvent sucré ?", a: ["Le petit-suisse", "Petit-suisse", "Petit suisse"], exp: "Inventé en Normandie par une fermière et un vacher suisse, vers 1850." },
    { id: 18270, theme: "Gastronomie", d: 1.0, q: "Quel fromage fondu en portions triangulaires a une vache rouge hilare sur sa boîte ?", a: ["La Vache qui rit", "Vache qui rit"], exp: "Créée en 1921 dans le Jura ; la vache a été dessinée par Benjamin Rabier." },
    { id: 18271, theme: "Gastronomie", d: 1.1, q: "Quel petit fromage rond est enveloppé dans de la cire rouge ?", a: ["Le Babybel", "Babybel", "Mini Babybel"], exp: "Fabriqué depuis 1952." },
    { id: 18272, theme: "Gastronomie", d: 1.1, q: "Quelle boisson mélange limonade et sirop de menthe ?", a: ["Le diabolo menthe", "Diabolo menthe", "Diabolo"], exp: "Aussi le titre d’un film de Diane Kurys (1977)." },
    { id: 18273, theme: "Gastronomie", d: 1.1, q: "Quelle boisson épaisse et froide mélange lait, glace et fruits ou chocolat ?", a: ["Le milk-shake", "Milk-shake", "Milkshake"], exp: "« Lait secoué » en anglais." },
    { id: 18274, theme: "Gastronomie", d: 1.2, q: "Quel dessert de pain rassis trempé dans du lait et de l’œuf est doré à la poêle ?", a: ["Le pain perdu", "Pain perdu"], exp: "Les Anglais l’appellent « French toast »." },
    { id: 18275, theme: "Gastronomie", d: 1.2, q: "Quel dessert de riz cuit longuement dans du lait sucré se mange froid ou tiède ?", a: ["Le riz au lait", "Riz au lait"], exp: "On l’aromatise souvent à la vanille ou à la cannelle." },
    { id: 18276, theme: "Gastronomie", d: 1.2, q: "Quel dessert américain met une banane coupée en deux avec trois boules de glace ?", a: ["Le banana split", "Banana split"], exp: "Inventé en 1904 en Pennsylvanie." },
    { id: 18277, theme: "Gastronomie", d: 1.3, q: "Quel œuf est cuit environ 6 minutes, avec le blanc ferme et le jaune coulant ?", a: ["L’œuf mollet", "Œuf mollet", "Oeuf mollet"], exp: "3 minutes : œuf à la coque ; 10 minutes : œuf dur." },
    { id: 18278, theme: "Gastronomie", d: 1.3, q: "Quel œuf est cuit sans coquille, plongé dans de l’eau frémissante vinaigrée ?", a: ["L’œuf poché", "Œuf poché", "Oeuf poché"], exp: "Indispensable aux œufs Bénédicte." },
    { id: 18279, theme: "Gastronomie", d: 1.3, q: "Quelle crêpe de blé noir est garnie de jambon, d’œuf et de fromage ?", a: ["La galette complète", "Galette complète", "Complète"], exp: "Une spécialité de Bretagne." },
    { id: 18280, theme: "Gastronomie", d: 1.4, q: "Avec quelle farine sombre fait-on les galettes bretonnes ?", a: ["Le sarrasin", "Sarrasin", "Blé noir", "Farine de sarrasin"], exp: "Malgré son nom de « blé noir », ce n’est pas une céréale." },
    { id: 18281, theme: "Gastronomie", d: 1.4, q: "Quelle douceur bretonne a été popularisée par Henri Le Roux à Quiberon en 1977 ?", a: ["Le caramel au beurre salé", "Caramel au beurre salé", "CBS"], exp: "Élu meilleur bonbon de France au Salon de Paris en 1980." },
    { id: 18282, theme: "Gastronomie", d: 1.5, q: "Quelle soupe gratinée, avec du pain et du fromage, se mangeait aux Halles de Paris au petit matin ?", a: ["La soupe à l’oignon", "Soupe à l’oignon", "Gratinée"], exp: "On l’appelle aussi « la gratinée »." },
    { id: 18283, theme: "Gastronomie", d: 1.5, q: "Quel plat du Pays basque cuit le poulet avec poivrons, tomates et piment ?", a: ["Le poulet basquaise", "Poulet basquaise", "Poulet à la basquaise"], exp: "Avec du piment d’Espelette." },
    { id: 18284, theme: "Gastronomie", d: 1.5, q: "Quel plat de moules est cuit au vin blanc, avec échalotes et persil ?", a: ["Les moules marinières", "Moules marinières", "Moules marinière"], exp: "Souvent servi avec des frites." },
    { id: 18285, theme: "Gastronomie", d: 1.6, q: "Quel gâteau rond du Pays basque est fourré à la crème ou à la confiture de cerises noires ?", a: ["Le gâteau basque", "Gâteau basque"], exp: "Les cerises viennent souvent d’Itxassou." },
    { id: 18286, theme: "Gastronomie", d: 1.6, q: "Quel dessert d’Escoffier associe pêches, glace vanille et coulis de framboise ?", a: ["La pêche Melba", "Pêche Melba", "Peche Melba"], exp: "Créée pour la cantatrice australienne Nellie Melba." },
    { id: 18287, theme: "Gastronomie", d: 1.6, q: "Quel dessert de poire pochée, glace vanille et chocolat chaud porte le nom d’une opérette ?", a: ["La poire Belle-Hélène", "Poire Belle-Hélène", "Belle-Hélène"], exp: "En hommage à « La Belle Hélène » d’Offenbach." },
    { id: 18288, theme: "Gastronomie", d: 1.7, q: "Quel dessert glacé mélange café, glace et chantilly, malgré son nom belge ?", a: ["Le café liégeois", "Café liégeois", "Liégeois"], exp: "Il s’appelait « café viennois » avant 1914 : la France a rendu hommage à la résistance de Liège." },
    { id: 18289, theme: "Gastronomie", d: 1.7, q: "Quelle gaufre belge épaisse contient des perles de sucre ?", a: ["La gaufre de Liège", "Gaufre de Liège", "Liège"], exp: "Celle de Bruxelles est plus légère et rectangulaire." },
    { id: 18290, theme: "Gastronomie", d: 1.8, q: "Quel ragoût flamand mijote du bœuf dans de la bière brune ?", a: ["La carbonade flamande", "Carbonade flamande", "Carbonnade", "Carbonade"], exp: "Avec une tranche de pain d’épices pour épaissir la sauce." },
    { id: 18291, theme: "Gastronomie", d: 1.9, q: "Quelles petites pâtes frites saupoudrées de sucre se mangent à Lyon pour Mardi gras ?", a: ["Les bugnes", "Bugnes", "Bugne"], exp: "Appelées merveilles ou oreillettes ailleurs." },
    { id: 18292, theme: "Gastronomie", d: 2.0, q: "Combien de desserts sert-on traditionnellement à Noël en Provence ?", a: ["13", "Treize"], exp: "Les « treize desserts », en souvenir du Christ et des apôtres." },
    { id: 18293, theme: "Gastronomie", d: 2.1, q: "Quel couteau pliant savoyard a une « main couronnée » sur sa lame ?", a: ["L’Opinel", "Opinel"], exp: "Créé en 1890 par Joseph Opinel." },
    { id: 18294, theme: "Gastronomie", d: 2.1, q: "Quel couteau aveyronnais est décoré d’une abeille (ou d’une mouche) sur le manche ?", a: ["Le Laguiole", "Laguiole", "Couteau Laguiole"], exp: "Beaucoup de « Laguiole » sont pourtant fabriqués loin de l’Aveyron." },
    { id: 18295, theme: "Gastronomie", d: 2.2, q: "Quelle cafetière italienne en métal fait monter le café par la vapeur ?", a: ["La cafetière italienne", "Cafetière italienne", "Moka", "Bialetti"], exp: "La Moka Bialetti, inventée en 1933." },
    { id: 18296, theme: "Gastronomie", d: 2.2, q: "Quelle casserole sous pression, inventée en France en 1953, cuit très vite ?", a: ["La Cocotte-Minute", "Cocotte-Minute", "Autocuiseur", "Cocotte minute"], exp: "Une marque de SEB devenue un nom courant." },
    { id: 18297, theme: "Gastronomie", d: 2.3, q: "Quelle poêle profonde et bombée sert à faire sauter les aliments en Asie ?", a: ["Le wok", "Wok"], exp: "On y cuit à feu très vif, en remuant sans arrêt." },
    { id: 18298, theme: "Gastronomie", d: 2.3, q: "Quelle plaque de cuisson espagnole en métal cuit à très haute température ?", a: ["La plancha", "Plancha"], exp: "« Plaque » en espagnol." },
    { id: 18299, theme: "Gastronomie", d: 2.5, q: "Quel fromage bourguignon, lavé au marc, a une croûte orangée et une forte odeur ?", a: ["L’époisses", "Époisses", "Epoisses"], exp: "Napoléon l’aurait apprécié." },
    { id: 18300, theme: "Gastronomie", d: 2.7, q: "Quel fromage normand est souvent moulé en forme de cœur ?", a: ["Le neufchâtel", "Neufchâtel", "Neufchatel"], exp: "Un des plus vieux fromages de Normandie." },
    { id: 18301, theme: "Gastronomie", d: 2.8, q: "Quel fromage bleu d’Auvergne, en haut cylindre, est l’un des plus doux des bleus ?", a: ["La fourme d’Ambert", "Fourme d’Ambert", "Fourme"], exp: "AOP depuis 1972." },
    { id: 18302, theme: "Gastronomie", d: 3.0, q: "Quelle boisson bretonne au miel fermenté est une sorte d’hydromel ?", a: ["Le chouchen", "Chouchen"], exp: "Il se boit en apéritif." }
